INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `RewardText`) VALUES
(975200, 1, 'Hrrmmgl.$B$B(The big murloc looks you up and down, unimpressed. He thumps his own chest twice, then yours once, much harder.)$B$BMrrrgllgh!'),
(975201, 1, '(Grrmlgrrl counts the cracked shells on his fingers, runs out of fingers, and gives up with a happy gurgle.)$B$BMrrrgl!'),
(975202, 1, '(Murlorga tips the mussels into the pot, shells and all. The smell is indescribable. Every murloc in the village turns its head at once.)$B$BMrglmrglmrgl!'),
(975203, 1, '(Blrrgl snatches the trinkets, holds each one up to his eye, and stuffs them into a hollow log already overflowing with spoons.)$B$BMrrgl mrgl!'),
(975204, 1, '(Blrrgl eats the first roll in one bite. He eats the second in one bite. He hides the other three under his fins and looks at you as if nothing happened.)'),
(975205, 1, '(Grrmlgrrl stamps the slithering lines flat, one by one, and roars until a fry runs to hide behind Murlorga.)$B$BMrglmrgl!'),
(975206, 1, '(Grrmlgrrl takes the trident in both hands and holds it over his head. The whole village gurgles at once, louder and louder, until he bangs it on the ground and they stop.)$B$B(He gives you a long look, and nods once.)'),
(975207, 1, '(Murlorga wraps each mussel in kelp and lays them in a row. Then she wraps one more and gives it to you, and watches until you eat it.)'),
(975208, 1, '(A small green murloc peers out from under the dock, sees you, and bursts into tears of relief. Or the sea. It\'s hard to tell with murlocs.)$B$Bmrgl? mrgl mrgl!'),
(975209, 1, '(Murlorga scoops Sloshy up, scolds him in a long, furious gurgle, then hugs him so hard he squeaks. Over his head, she looks at you, and her eyes are wet.)$B$BMrgl.'),
(975210, 1, '(Oracle Glubbub lays the coral in a circle around himself and sits in the middle of it, humming a low, bubbling hum. The coral pulses with him.)'),
(975211, 1, '(Oracle Glubbub drops the eyes into the coral circle, one by one. He stares into them for a long time. Then he looks up at you, very differently than before.)'),
(975212, 1, '(Blrrgl opens the box. The lures shine. Blrrgl shines. He hangs every single one of them from his fins and jingles away down the beach.)'),
(975213, 1, '(Elder Mrrglmrgl turns the pearl over and over in his hands. Then he gives it back to you, and closes your fingers around it.)'),
(975214, 1, '(Oracle Glubbub listens as you gurgle what you saw: the elves\' town, the slithering ones on their islands, the long coast to the south. He nods slowly, as if you told him something he already knew.)'),
(975215, 1, '(The pearl settles into the altar\'s shell with a soft click. Behind you, the whole village erupts in gurgling cheers. Grrmlgrrl lifts you off your feet. Murlorga cries. Blrrgl steals something from your pack in the confusion and gives it back.)'),
(975216, 1, 'A murloc... carrying a letter. Well. Stranger things have washed up in Auberdine, though not many.$B$BIf you mean us no harm, little one, there is more than enough work here for anyone who would help. The Highborne ruins, the corrupted furbolgs, the creatures of the coast... Darkshore is sick, and we could use every hand. Even a webbed one.'),
(975230, 1, 'Then the water around us is ours again, for now. You fight like one who remembers the old drills. We all do. That is what frightens them.'),
(975231, 1, 'These are Stormscale seals. Real ones.$B$B...I will not pretend I am glad to see your kind on my docks. Ten thousand years ago your people drowned my world, and the Stormscale still kill my sentinels on this very coast. But you brought me their plans, and I am not too proud to read them.$B$BYou may stay. Help us, and we will see. Betray us, and the sentinels have long memories.'),
(975232, 1, 'Mon, you got a death wish? Walkin\' up on me like dat, scales and all... Ha! Lucky for you, you ain\'t one of dem Wrathtail, or you\'d have a spear in ya already.$B$BZun\'jin of the Darkspear. Scouting dis beach for Zoram\'gar.'),
(975233, 1, 'Ha! Dat\'s how it\'s done! You fight like you got somethin\' to prove, mon. I like dat.'),
(975234, 1, 'Zun\'jin sent a naga to my outpost. A naga.$B$B...He says you fought beside him, and that the Wrathtail hate you more than they hate us. That counts for something. Not everything. Something.$B$BThe Horde is made of those the world threw away, so I will not throw you away before I see what you are. The Wrathtail are your people\'s enemies and ours. Show me what you will do to them.');
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`) VALUES
(975201, 6, 6, '(Grrmlgrrl holds up both hands and wiggles every finger. Then he points at the beach.)'),
(975202, 6, 6, '(Murlorga taps the empty pot with her ladle. Tonk. Tonk.)'),
(975203, 6, 6, '(Blrrgl rubs his fingers together, very fast.)'),
(975204, 6, 6, '(Blrrgl pats his stomach and makes a small, pitiful noise.)'),
(975205, 6, 6, '(Grrmlgrrl draws another slithering line in the sand. It isn\'t stabbed yet.)'),
(975206, 6, 6, '(Grrmlgrrl stares at your empty hands, then at the island to the south.)'),
(975207, 6, 6, '(Murlorga holds up the unwrapped mussel and shakes her head.)'),
(975209, 6, 6, '(Sloshy is still holding on to your leg.)'),
(975210, 6, 6, '(Oracle Glubbub\'s hands are still cupped, still empty.)'),
(975211, 6, 6, '(Oracle Glubbub taps his eye again and waits.)'),
(975212, 6, 6, '(Blrrgl looks at the dock, then at you, then at the dock.)'),
(975213, 6, 6, '(Elder Mrrglmrgl draws the circle in the air again, slower.)'),
(975214, 6, 6, '(Oracle Glubbub points at the top of the island again.)'),
(975215, 6, 6, '(The shell at the altar\'s top is empty.)'),
(975230, 6, 6, 'The Stormscale still wait on the northern island.'),
(975231, 6, 6, 'Speak quickly, naga. My archers are watching you.'),
(975233, 6, 6, 'Still hearin\' dem hiss out dere.');
