-- The Murlocs and the Naga (mod-murloc-naga): generated by tools/build_data.py from the game's own tables,
-- the core's world SQL, the server's maps and tools/content.py; edit those, not this. Safe to run again:
-- every row is replaced, every mask OR'd, every id the module's own.

-- The murlocs' models (CreatureModelData) and looks (CreatureDisplayInfo); the naga wear the game's own.

-- The races: Murloc (19, the Alliance's, the night elves' standing) and Naga (20, the Horde's, the trolls'); the
-- game's Taunka and Northrend Skeleton, which only creatures are, moved to 30 and 31.

-- Their looks; the creatures' races 19 and 20 moved to 30 and 31.
DELETE FROM `charsections_dbc` WHERE `ID` BETWEEN 860000 AND 869999;

-- Their classes' starting gear: their kin's for the class (or the nearest race's).

-- Skills and abilities open to either side's races are open to theirs (the racials and languages aside).
ON DUPLICATE KEY UPDATE `RaceMask` = IF(((`RaceMask` | VALUES(`RaceMask`)) & 0xFFFFFFFF) >= 0x80000000, CAST(((`RaceMask` | VALUES(`RaceMask`)) & 0xFFFFFFFF) AS SIGNED) - 4294967296, ((`RaceMask` | VALUES(`RaceMask`)) & 0xFFFFFFFF));
ON DUPLICATE KEY UPDATE `RaceMask` = IF(((`RaceMask` | VALUES(`RaceMask`)) & 0xFFFFFFFF) >= 0x80000000, CAST(((`RaceMask` | VALUES(`RaceMask`)) & 0xFFFFFFFF) AS SIGNED) - 4294967296, ((`RaceMask` | VALUES(`RaceMask`)) & 0xFFFFFFFF));

-- Standing: their kin's (the night elves' for the murlocs, the trolls' for the naga). The naga are neutral to the
-- night elves of Darnassus, the Explorers' League (Ironforge) and the Gnomeregan Exiles, whose people they meet in
-- Darkshore, where the Horde's other races are hated: the core and the game take a reputation faction's people's
-- reaction from the character's own standing with it, so those people talk to the naga alone of the Horde, and
-- their guards leave them be. The first of a faction's four slots that names the race gives its standing; the
-- naga's are put in the last, free slot of those three factions (and in no other slot of theirs).
ON DUPLICATE KEY UPDATE `ReputationRaceMask_1` = IF(((`ReputationRaceMask_1` | VALUES(`ReputationRaceMask_1`)) & 0xFFFFFFFF) >= 0x80000000, CAST(((`ReputationRaceMask_1` | VALUES(`ReputationRaceMask_1`)) & 0xFFFFFFFF) AS SIGNED) - 4294967296, ((`ReputationRaceMask_1` | VALUES(`ReputationRaceMask_1`)) & 0xFFFFFFFF)), `ReputationRaceMask_2` = IF(((`ReputationRaceMask_2` | VALUES(`ReputationRaceMask_2`)) & 0xFFFFFFFF) >= 0x80000000, CAST(((`ReputationRaceMask_2` | VALUES(`ReputationRaceMask_2`)) & 0xFFFFFFFF) AS SIGNED) - 4294967296, ((`ReputationRaceMask_2` | VALUES(`ReputationRaceMask_2`)) & 0xFFFFFFFF)), `ReputationRaceMask_3` = IF(((`ReputationRaceMask_3` | VALUES(`ReputationRaceMask_3`)) & 0xFFFFFFFF) >= 0x80000000, CAST(((`ReputationRaceMask_3` | VALUES(`ReputationRaceMask_3`)) & 0xFFFFFFFF) AS SIGNED) - 4294967296, ((`ReputationRaceMask_3` | VALUES(`ReputationRaceMask_3`)) & 0xFFFFFFFF)), `ReputationRaceMask_4` = IF(((`ReputationRaceMask_4` | VALUES(`ReputationRaceMask_4`)) & 0xFFFFFFFF) >= 0x80000000, CAST(((`ReputationRaceMask_4` | VALUES(`ReputationRaceMask_4`)) & 0xFFFFFFFF) AS SIGNED) - 4294967296, ((`ReputationRaceMask_4` | VALUES(`ReputationRaceMask_4`)) & 0xFFFFFFFF));
UPDATE `faction_dbc` SET `ReputationBase_4` = 0, `ReputationFlags_4` = 1 WHERE `ID` IN (69, 47, 54);

-- Their racials, and their phases (seen in Darkshore and Ashenvale: spell_area).

-- The intros: a flight over each race's home, with its own narration (put together by the patch from the game's
-- sounds: data/client/narration.txt).

-- Their homes: the murlocs' village, the naga's camp, their enemies, the things they steal, in their own phases.
DELETE FROM `creature_template` WHERE `entry` BETWEEN 975000 AND 975099;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 975000 AND 975099;
DELETE FROM `creature` WHERE `guid` BETWEEN 9750000 AND 9750999;
DELETE FROM `npc_text` WHERE `ID` BETWEEN 975400 AND 975499;
DELETE FROM `gossip_menu` WHERE `MenuID` BETWEEN 975000 AND 975099;
DELETE FROM `npc_vendor` WHERE `entry` BETWEEN 975000 AND 975099;
DELETE FROM `gameobject_template` WHERE `entry` BETWEEN 975100 AND 975199;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 9751000 AND 9751999;
DELETE FROM `gameobject_loot_template` WHERE `Entry` BETWEEN 975100 AND 975199;
DELETE FROM `creature_loot_template` WHERE `Comment` = 'mod-murloc-naga';
DELETE FROM `gameobjectdisplayinfo_dbc` WHERE `ID` BETWEEN 9750 AND 9799;

-- Their quest items and rewards.
DELETE FROM `item_template` WHERE `entry` BETWEEN 975300 AND 975399;

-- Their quests: the murlocs' (all theirs: murloc words, every giver a murloc) and the naga's (their start, and the way
-- to the Horde after Darkshore: Onu at the Grove of the Ancients, a Darkspear scout at the Zoram Strand, Marukai at
-- Zoram'gar, whose Naga at the Zoram Strand (6442) is the Horde's own).
DELETE FROM `quest_template` WHERE `ID` BETWEEN 975200 AND 975299;
DELETE FROM `quest_template_addon` WHERE `ID` BETWEEN 975200 AND 975299;
DELETE FROM `quest_offer_reward` WHERE `ID` BETWEEN 975200 AND 975299;
