UPDATE `playercreateinfo_skills` SET `raceMask` = `raceMask` | 262144 WHERE (`raceMask` & 2047) = 1024 AND `classMask` = 4 AND `skill` = 226;
UPDATE `playercreateinfo_skills` SET `raceMask` = `raceMask` | 786432 WHERE (`raceMask` & 2047) = 1061 AND `classMask` = 3 AND `skill` = 160;
UPDATE `playercreateinfo_skills` SET `raceMask` = `raceMask` | 262144 WHERE (`raceMask` & 2047) = 1101 AND `classMask` = 0 AND `skill` = 98;

